/// Look up the static message catalog for a locale.
pub const fn for_locale(locale: Locale) -> &'static Catalog {
    match locale {
        Locale::En => &EN,
        Locale::De => &DE,
        Locale::Es => &ES,
        Locale::Fr => &FR,
        Locale::It => &IT,
        Locale::PtBr => &PTBR,
        Locale::Nl => &NL,
        Locale::Ru => &RU,
        Locale::Uk => &UK,
        Locale::Ja => &JA,
        Locale::Ko => &KO,
        Locale::ZhCn => &ZHCN,
        Locale::ZhTw => &ZHTW,
        Locale::Ar => &AR,
        Locale::Hi => &HI,
        Locale::Pl => &PL,
        Locale::Tr => &TR,
        Locale::Sv => &SV,
        Locale::Vi => &VI,
        Locale::Id => &ID,
        Locale::AfZa => &AF_ZA,
        Locale::AmEt => &AM_ET,
        Locale::ArEg => &AR_EG,
        Locale::ArMa => &AR_MA,
        Locale::FrMa => &FR_MA,
        Locale::FrSn => &FR_SN,
        Locale::HaNg => &HA_NG,
        Locale::IgNg => &IG_NG,
        Locale::MgMg => &MG_MG,
        Locale::RwRw => &RW_RW,
        Locale::SoSo => &SO_SO,
        Locale::SwKe => &SW_KE,
        Locale::XhZa => &XH_ZA,
        Locale::YoNg => &YO_NG,
        Locale::ZuZa => &ZU_ZA,
        Locale::Bn => &BN,
        Locale::Fa => &FA,
        Locale::He => &HE,
        Locale::Mr => &MR,
        Locale::Ta => &TA,
        Locale::Te => &TE,
        Locale::Th => &TH,
        Locale::Ur => &UR,
        Locale::Ms => &MS,
        Locale::Fil => &FIL,
    }
}

